                ret.CellMax = this.CellMax.Combine(rhs.CellMax);
                ret.HeightRange = this.HeightRange.Combine(rhs.HeightRange, (l, r) => l.Combine(r));
                ret.SourceBlock = this.SourceBlock.Combine(rhs.SourceBlock);
                return ret;
            }
